import os
import stat
from collections import deque
from typing import Iterator, Sequence


def walk(paths: Sequence[str], *, follow: str = "P", sorted_entries: bool = False,
         postorder: bool = False, mindepth: int = 0, maxdepth: int | None = None,
         unique: bool = False, xdev: bool = False, nohidden: bool = False) -> Iterator[tuple[str, int, os.stat_result | None]]:
    """Yield (path, depth, stat) in bfs order, or postorder DFS when requested.

    ``follow`` is P (never), H (command-line roots only), or L (all links).
    Missing/unreadable paths are yielded with a None stat result; caller owns
    diagnostics. Directory traversal uses a per-directory sorted order if asked.
    """
    roots = list(paths) or ["."]
    seen: set[tuple[int, int]] = set()
    root_ids: list[tuple[int, int] | None] = []

    def getstat(path: str, root: bool) -> os.stat_result | None:
        try:
            if follow == "L" or (follow == "H" and root):
                return os.stat(path)
            return os.lstat(path)
        except OSError:
            return None

    for root in roots:
        st = getstat(root, True)
        root_ids.append((st.st_dev, st.st_ino) if st else None)

    def children(path: str) -> list[str]:
        try:
            with os.scandir(path) as entries:
                result = [os.path.join(path, ent.name) for ent in entries]
        except OSError:
            return []
        if sorted_entries:
            result.sort(key=lambda p: os.fsencode(os.path.basename(p)))
        if nohidden:
            result = [p for p in result if not os.path.basename(p).startswith(".")]
        return result

    def directory(st: os.stat_result | None) -> bool:
        return st is not None and stat.S_ISDIR(st.st_mode)

    def allowed(path: str, root: bool, st: os.stat_result | None) -> bool:
        if st is None:
            return True
        ident = (st.st_dev, st.st_ino)
        if unique:
            if ident in seen:
                return False
            seen.add(ident)
        if xdev and root_ids and root_ids[0] and st.st_dev != root_ids[0][0]:
            return False
        return True

    if not postorder:
        queue = deque((p, 0, True, frozenset()) for p in roots)
        while queue:
            path, depth, root, ancestors = queue.popleft()
            st = getstat(path, root)
            if directory(st) and (st.st_dev, st.st_ino) in ancestors:
                continue
            if not allowed(path, root, st):
                continue
            if depth >= mindepth:
                yield path, depth, st
            if directory(st) and (maxdepth is None or depth < maxdepth):
                ident = (st.st_dev, st.st_ino)
                if ident not in ancestors:
                    queue.extend((child, depth + 1, False, ancestors | {ident}) for child in children(path))
    else:
        # Iterative postorder DFS avoids recursion limits on deep trees.
        stack: list[tuple[str, int, bool, bool, os.stat_result | None, frozenset[tuple[int, int]]]] = [
            (p, 0, True, False, None, frozenset()) for p in reversed(roots)
        ]
        while stack:
            path, depth, root, expanded, cached, ancestors = stack.pop()
            st = cached if expanded else getstat(path, root)
            if not expanded:
